-- Venue Live Guest "Jazz Night". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara jazznight), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'jazznight', 'Jazz Night (malam jazz)', 'jazznight', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 135, 'center 38%',
  $t${"name":"Jazz Night","orn":"diamond","ui":{"ivory":"#F8F0FB","white":"#FFFFFF","soft":"#E9D6F2","soft2":"#BE92D6","accent":"#7A2E91","deep":"#3A1450","ink":"#2A1038","mute":"#8A6A9A","line":"#E2CBEE","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FCF8FE","ink":"#2A1038","accent":"#7A2E91","gold":"#D9A21B","leaf":"#E9D6F2","hbg":"rgba(248,240,251,.94)","hline":"#BE92D6","motif":"diamond"},"hud":{"bg":"rgba(58,20,80,.9)","acc":"#FFC94D","on":"#2A1038"},"scr":{"wine":"#3A1450","veil":"248,240,251"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'jazznight');
